import 'package:flutter/material.dart';import '../../core/hotels/hotel_repository.dart';import '../../core/state/app_controller.dart';
class HotelOwnerAddScreen extends StatefulWidget{const HotelOwnerAddScreen({super.key});@override State<HotelOwnerAddScreen>createState()=>_S();}class _S extends State<HotelOwnerAddScreen>{final f=GlobalKey<FormState>();final n=TextEditingController(),a=TextEditingController(),city=TextEditingController(),district=TextEditingController(),phone=TextEditingController(),desc=TextEditingController(),lat=TextEditingController(),lng=TextEditingController();bool busy=false;@override Widget build(BuildContext c)=>SafeArea(child:Form(key:f,child:ListView(padding:const EdgeInsets.all(14),children:[const Text('Add Hotel',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const Text('Your hotel will remain hidden until admin approval.',style:TextStyle(fontSize:10,color:Colors.black54)),const SizedBox(height:14),for(final x in [('Hotel name',n),('Address',a),('City',city),('District',district),('Phone',phone),('Description',desc),('Latitude',lat),('Longitude',lng)])Padding(padding:const EdgeInsets.only(bottom:9),child:TextFormField(controller:x.$2,style:const TextStyle(fontSize:12),validator:(v)=>v==null||v.trim().isEmpty?'Required':null,decoration:InputDecoration(labelText:x.$1,isDense:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14))))),FilledButton(onPressed:busy?null:_save,child:Text(busy?'Submitting...':'Submit for approval'))])));Future<void>_save()async{if(!f.currentState!.validate())return;setState(()=>busy=true);try{await HotelRepository(AppControllerScope.of(context).apiClient).createHotel({'name':n.text,'description':desc.text,'address':a.text,'city':city.text,'district':district.text,'latitude':double.tryParse(lat.text)??0,'longitude':double.tryParse(lng.text)??0,'contactPhone':phone.text,'mainImageUrl':'','amenities':<String>[],'transportAvailable':true});if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Hotel submitted for admin approval.')));for(final c in[n,a,city,district,phone,desc,lat,lng])c.clear();}}finally{if(mounted)setState(()=>busy=false);}}
}
